#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>

#define GPIO_PIN_2 2
#define GPIO_PIN_3 3
#define INTERVAL_US 100000 // 0.1 seconds

volatile sig_atomic_t keep_running = true;

void signal_handler(int signum) {
    keep_running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line2, *line3;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!line2 || !line3) {
        perror("Failed to get GPIO lines");
        goto cleanup;
    }

    // Request lines as output
    ret = gpiod_line_request_output(line2, "output2", 0);
    if (ret < 0) {
        perror("Failed to request line 2 as output");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line3, "output3", 0);
    if (ret < 0) {
        perror("Failed to request line 3 as output");
        goto cleanup;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int state = 0;
    while (keep_running) {
        // Set GPIO 2 and 3 to the current state
        gpiod_line_set_value(line2, state);
        gpiod_line_set_value(line3, state);

        // Report the state
        printf("GPIO 2: %d, GPIO 3: %d\n", state, state);

        // Toggle state
        state = 1 - state;

        // Sleep for 0.1 seconds
        usleep(INTERVAL_US);
    }

cleanup:
    // Release resources
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

