#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDRESS 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define I2C_SLAVE_FORCE 0x0706

static int i2c_fd;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_msg messages[2];
    __u8 write_buf[3], read_buf[2];
    int ret;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE_FORCE, ADS1115_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    write_buf[0] = CONFIG_REG;
    write_buf[1] = 0x8583; // Configuration for single-shot mode, AIN0, 128SPS
    write_buf[2] = 0x83;   // High byte of gain and data rate

    messages[0].addr = ADS1115_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 3;
    messages[0].buf = write_buf;

    messages[1].addr = ADS1115_ADDRESS;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 2;
    messages[1].buf = read_buf;

    while (1) {
        ret = write(i2c_fd, write_buf, 3);
        if (ret != 3) {
            perror("Failed to write to ADS1115");
            break;
        }

        usleep(10000); // Wait for conversion to complete

        ret = writev(i2c_fd, messages, 2);
        if (ret != 2) {
            perror("Failed to read from ADS1115");
            break;
        }

        int16_t adc_value = (read_buf[0] << 8) | read_buf[1];
        printf("ADC Value: %d\n", adc_value);

        sleep(1); // Wait for 0.5 seconds before next reading
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define MLX90614_RAWIR1 0x04
#define I2C_SLAVE_FORCE 0x0706

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int file;
    uint16_t data;
    float temperature;
    struct i2c_msg messages[1];
    struct i2c_rdwr_ioctl_data packets;

    // Open I2C bus
    file = open(I2C_BUS, O_RDWR);
    if (file < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    // Set the I2C slave address for the MLX90614
    if (ioctl(file, I2C_SLAVE_FORCE, MLX90614_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(file);
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        // Prepare the I2C message
        messages[0].addr = MLX90614_ADDR;
        messages[0].flags = 0;
        messages[0].len = 2;
        messages[0].buf = (uint8_t *)&data;

        // Read the raw IR temperature value
        packets.msgs = messages;
        packets.nmsgs = 1;
        if (ioctl(file, I2C_RDWR, &packets) < 0) {
            perror("Failed to read from the MLX90614");
            close(file);
            return EXIT_FAILURE;
        }

        // Convert the raw value to temperature in Celsius
        temperature = (data * 0.02) - 273.15;
        printf("Temperature: %.2f°C\n", temperature);

        // Wait for 5 seconds
        sleep(5);
    }

    // Close the I2C bus
    close(file);
    return EXIT_SUCCESS;
}

