#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 128  // 50% duty cycle
#define INTERVAL_MS 500

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        if (gpioPWM(PWM_PIN, PWM_DUTY_CYCLE) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }
        printf("PWM state: ON\n");
        time_sleep(INTERVAL_MS / 1000.0);

        if (gpioPWM(PWM_PIN, 0) < 0) {
            fprintf(stderr, "Failed to turn off PWM\n");
            break;
        }
        printf("PWM state: OFF\n");
        time_sleep(INTERVAL_MS / 1000.0);
    }

    gpioSetPWMfrequency(PWM_PIN, 0);  // Disable PWM
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define DEVICE_PATH "/dev/gpiochip0"
#define TIMEOUT 1000000 // 1 second in microseconds

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile sig_atomic_t keep_running = 1;

void cleanup(int signum) {
    keep_running = 0;
}

int setup_gpio() {
    chip = gpiod_chip_open(DEVICE_PATH);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!trigger_line || !echo_line) {
        fprintf(stderr, "Error getting GPIO lines\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "HC-SR04 Trigger", 0) < 0 ||
        gpiod_line_request_input(echo_line, "HC-SR04 Echo") < 0) {
        fprintf(stderr, "Error requesting GPIO lines\n");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void release_gpio() {
    if (echo_line) gpiod_line_release(echo_line);
    if (trigger_line) gpiod_line_release(trigger_line);
    if (chip) gpiod_chip_close(chip);
}

int measure_distance() {
    struct timespec start, end;
    int64_t duration;

    // Send 10us pulse to trigger
    gpiod_line_set_value(trigger_line, 1);
    nanosleep(&(struct timespec){0, 10000}, NULL);
    gpiod_line_set_value(trigger_line, 0);

    // Wait for echo
    clock_gettime(CLOCK_MONOTONIC, &start);
    do {
        if (gpiod_line_get_value(echo_line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            duration = (end.tv_sec - start.tv_sec) * 1000000LL + (end.tv_nsec - start.tv_nsec) / 1000;
            if (duration > TIMEOUT) {
                fprintf(stderr, "Echo pulse timeout\n");
                return -1;
            }
        }
    } while (duration <= 0 || duration > TIMEOUT);

    // Calculate distance (speed of sound ~343 m/s, round trip)
    return (int)((duration / 2) / 58); // Convert to cm
}

int main() {
    if (setup_gpio() != 0) {
        fprintf(stderr, "Failed to setup GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (keep_running) {
        int distance = measure_distance();
        if (distance >= 0) {
            printf("Distance: %d cm\n", distance);
        } else {
            printf("Measurement failed\n");
        }
        sleep(60);
    }

    release_gpio();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDRESS 0x28
#define CONVERSION_REG 0x00
#define CONFIG_REG 0x01
#define CHANNEL 0
#define SAMPLE_RATE 0x0800 // 128SPS
#define PGA 0x0400 // +/- 2.048V
#define MODE 0x0000 // Continuous conversion mode

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int write_i2c(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    return write(fd, buf, 3);
}

int read_i2c(int fd) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

int main() {
    int fd;
    int16_t adc_value;
    float voltage;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return EXIT_FAILURE;
    }

    // Configure ADS1115
    if (write_i2c(fd, CONFIG_REG, CHANNEL | PGA | SAMPLE_RATE | MODE) != 3) {
        perror("Failed to configure ADS1115");
        close(fd);
