int main() {
    int16_t adc_value;
    uint16_t config = 0x8483; // Single-shot mode, AIN0, 128SPS

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t config_bytes[3] = {ADS1115_CONFIG_REG, (config >> 8) & 0xFF, config & 0xFF};
    if (write(i2c_fd, config_bytes, sizeof(config_bytes)) != sizeof(config_bytes)) {
        perror("Failed to write configuration");
        cleanup(0);
    }

    usleep(100000); // Wait for conversion to complete

    uint8_t read_bytes[2] = {ADS1115_CONVERSION_REG, 0};
    if (read(i2c_fd, read_bytes, sizeof(read_bytes)) != sizeof(read_bytes)) {
        perror("Failed to read ADC value");
        cleanup(0);
    }

    adc_value = (read_bytes[0] << 8) | read_bytes[1];
    printf("ADC Value: %d\n", adc_value);

    cleanup(0);
    return EXIT_SUCCESS;
}

