#define SI7021_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define I2C_TIMEOUT 1000 // 1 second

static int i2c_fd;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

int write_i2c(int fd, uint8_t *buf, int len) {
    if (write(fd, buf, len) != len) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int read_i2c(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int si7021_measure(int fd) {
    uint8_t cmd = 0xF3; // Measure Relative Humidity, Hold Master Mode
    if (write_i2c(fd, &cmd, 1) < 0) return -1;

    usleep(50000); // Wait for measurement to complete

    uint8_t data[2];
    if (read_i2c(fd, data, 2) < 0) return -1;

    uint16_t raw = (data[0] << 8) | data[1];
    float humidity = (125.0f * raw / 65536.0f) - 6.0f;

    if (humidity < 0 || humidity > 100) {
        fprintf(stderr, "Invalid humidity reading: %f%%\n", humidity);
        return -1;
    }

    printf("Humidity: %.2f%%\n", humidity);
    return 0;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SI7021_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        if (si7021_measure(i2c_fd) < 0) {
            fprintf(stderr, "Error reading from SI7021\n");
        }

        clock_gettime(CLOCK_MONOTONIC, &current);
        double elapsed = (current.tv_sec - start.tv_sec) + (current.tv_nsec - start.tv_nsec) / 1e9;
        if (elapsed >= 5.0) {
            start = current;
        }

        sleep(1);
    }

    return 0;
}

