#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUDRATE B9600
#define BUFFER_SIZE 256

static int serial_fd = -1;

void cleanup(int signum) {
    if (serial_fd != -1) {
        close(serial_fd);
    }
    exit(EXIT_FAILURE);
}

int main() {
    struct termios tty;
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    // Open the serial port
    serial_fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (serial_fd < 0) {
        fprintf(stderr, "Error %d opening %s: %s\n", errno, SERIAL_PORT, strerror(errno));
        return EXIT_FAILURE;
    }

    // Configure the serial port
    if (tcgetattr(serial_fd, &tty) != 0) {
        fprintf(stderr, "Error %d from tcgetattr: %s\n", errno, strerror(errno));
        close(serial_fd);
        return EXIT_FAILURE;
    }

    cfsetospeed(&tty, BAUDRATE);
    cfsetispeed(&tty, BAUDRATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;                         // disable break processing
    tty.c_lflag = 0;                                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;                            // read doesn't block
    tty.c_cc[VTIME] = 5;                            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);         // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);                // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD);              // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS

    if (tcsetattr(serial_fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error %d from tcsetattr: %s\n", errno, strerror(errno));
        close(serial_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler for cleanup
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Read from the serial port
    bytes_read = read(serial_fd, buffer, sizeof(buffer) - 1);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
        cleanup(0);
    }

    buffer[bytes_read] = '\0';
    printf("Read from serial: %s\n", buffer);

    // Clean up and exit
    close(serial_fd);
    return EXIT_SUCCESS;
}

