#define GPIO_PIN1 23
#define GPIO_PIN2 24
#define GPIO_PIN3 25
#define INTERVAL_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2, *line3;
static volatile bool running = true;

void signal_handler(int signum) {
    running = false;
}

int main() {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    line1 = gpiod_chip_get_line(chip, GPIO_PIN1);
    line2 = gpiod_chip_get_line(chip, GPIO_PIN2);
    line3 = gpiod_chip_get_line(chip, GPIO_PIN3);

    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        goto cleanup;
    }

    // Request lines as output
    ret = gpiod_line_request_output(line1, "output1", 0);
    if (ret < 0) goto cleanup;
    ret = gpiod_line_request_output(line2, "output2", 0);
    if (ret < 0) goto cleanup;
    ret = gpiod_line_request_output(line3, "output3", 0);
    if (ret < 0) goto cleanup;

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Set GPIO 23 to HIGH
        gpiod_line_set_value(line1, 1);
        // Set GPIO 24 to LOW
        gpiod_line_set_value(line2, 0);
        // Toggle GPIO 25
        static int toggle_state = 0;
        gpiod_line_set_value(line3, toggle_state);
        toggle_state = !toggle_state;

        printf("GPIO 23: HIGH, GPIO 24: LOW, GPIO 25: %s\n", toggle_state ? "HIGH" : "LOW");

        usleep(INTERVAL_MS * 1000);
    }

cleanup:
    // Release resources
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_PIN 17
#define DEVICE_PATH "/dev/gpiochip0"
#define TIMEOUT_US 1000000  // 1 second timeout

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open(DEVICE_PATH);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    int state = 0;
    while (keep_running) {
        ret = gpiod_line_set_value(line, state);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO value\n");
        } else {
            printf("GPIO %d set to %d\n", GPIO_PIN, state);
        }

        state = !state;  // Toggle state

        // Sleep for 1 millisecond
        usleep(1000);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

