#define GPIO_OUT1 2
#define GPIO_OUT2 3
#define DEVICE_PATH "/dev/gpiochip0"
#define VALIDITY_CHECK(value) ((value) == 0 || (value) == 1)

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int ret;
    int state1 = 0, state2 = 1;

    chip = gpiod_chip_open(DEVICE_PATH);
    if (!chip) {
        fprintf(stderr, "Error: Unable to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_OUT1);
    line2 = gpiod_chip_get_line(chip, GPIO_OUT2);

    if (!line1 || !line2) {
        fprintf(stderr, "Error: Unable to get GPIO lines\n");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line1, "output1", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Unable to request line %d as output\n", GPIO_OUT1);
        goto cleanup;
    }

    ret = gpiod_line_request_output(line2, "output2", 1);
    if (ret < 0) {
        fprintf(stderr, "Error: Unable to request line %d as output\n", GPIO_OUT2);
        goto cleanup;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        if (!VALIDITY_CHECK(state1) || !VALIDITY_CHECK(state2)) {
            fprintf(stderr, "Error: Invalid state value\n");
            goto cleanup;
        }

        ret = gpiod_line_set_value(line1, state1);
        if (ret < 0) {
            fprintf(stderr, "Error: Unable to set GPIO %d\n", GPIO_OUT1);
            goto cleanup;
        }

        ret = gpiod_line_set_value(line2, state2);
        if (ret < 0) {
            fprintf(stderr, "Error: Unable to set GPIO %d\n", GPIO_OUT2);
            goto cleanup;
        }

        printf("GPIO %d set to %d, GPIO %d set to %d\n", GPIO_OUT1, state1, GPIO_OUT2, state2);

        state1 = !state1;
        state2 = !state2;

        sleep(5);
    }

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    return (ret < 0) ? EXIT_FAILURE : EXIT_SUCCESS;
