int main() {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Unable to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
