#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>

#define DHT_PIN 4
#define MAX_RETRIES 5
#define TIMEOUT_US 100000

// DHT11 timing constants
#define DHT11_START_DELAY_US 18000
#define DHT11_DATA_DELAY_US 20

// Function prototypes
int read_dht11(int gpio);
void cleanup(int gpio, struct gpiod_chip *chip, struct gpiod_line *line);

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = 0;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, DHT_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line\n");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    // Request line as output
    if (gpiod_line_request_output(line, "DHT11", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output\n");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    // Read DHT11
    ret = read_dht11(DHT_PIN);

cleanup:
    cleanup(DHT_PIN, chip, line);
    return ret;
}

int read_dht11(int gpio) {
    int retries = 0;
    int data[5] = {0};
    int sum = 0;
    int bit = 0;
    int byte = 0;
    struct timespec start, current;

    while (retries < MAX_RETRIES) {
        // Start signal
        gpiod_line_set_value(gpio, 1);
        usleep(DHT11_START_DELAY_US);
        gpiod_line_set_value(gpio, 0);

        // Wait for response
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(gpio) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &current);
            if ((current.tv_sec - start.tv_sec) * 1000000 + 
                (current.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_US) {
                break;
            }
        }

        // Check for response
        if (gpiod_line_get_value(gpio) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &start);
            while (gpiod_line_get_value(gpio) == 1) {
                clock_gettime(CLOCK_MONOTONIC, &current);
                if ((current.tv_sec - start.tv_sec) * 1000000 + 
                    (current.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_US) {
                    break;
                }
            }

            // Read data
            for (int i = 0; i < 40; i++) {
                clock_gettime(CLOCK_MONOTONIC, &start);
                while (gpiod_line_get_value(gpio) == 0) {
                    clock_gettime(CLOCK_MONOTONIC, &current);
                    if ((current.tv_sec - start.tv_sec) * 1000000 + 
                        (current.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_US) {
                        return EXIT_FAILURE;
                    }
                }

                usleep(DHT11_DATA_DELAY_US);

                if (gpiod_line_get_value(gpio) == 1) {
                    data[byte] |= (1 << (7 - bit));
                }

                if (++bit == 8) {
                    bit = 0;
                    if (++byte == 5) {
                        break;
                    }
                }

                clock_gettime(CLOCK_MONOTONIC, &start);
                while (gpiod_line_get_value(gpio) == 1) {
                    clock_gettime(CLOCK_MONOTONIC, &current);
                    if ((current.tv_sec - start.tv_sec) * 1000000 + 
                        (current.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_US) {
                        return EXIT_FAILURE;
                    }
                }
            }

            // Validate checksum
            sum = data[0] + data[1] + data[2] + data[3];
            if (sum != data[4]) {
                fprintf(stderr, "Checksum error\n");
                retries++;
                continue;
            }

            // Print data
            printf("Temperature: %d.%d°C\n", data[2], data[3]);
            printf("Humidity: %d.%d%%\n", data[0], data[1]);
            return EXIT_SUCCESS;
        }

        retries++;
    }

    fprintf(stderr, "Failed to read DHT11\n");
    return EXIT_FAILURE;
}

void cleanup(int gpio, struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

