    keep_running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line2, *line3, *line17;
    int ret;

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open(CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    line17 = gpiod_chip_get_line(chip, GPIO_PIN_17);

    if (!line2 || !line3 || !line17) {
        fprintf(stderr, "Error getting GPIO lines\n");
        goto cleanup;
    }

    // Request lines as outputs
    ret = gpiod_line_request_output(line2, "output2", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO 2 as output\n");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line3, "output3", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO 3 as output\n");
        goto cleanup;
