#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define PWM_PIN1 2
#define PWM_PIN2 3
#define PWM_PIN3 18
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 128
#define SLEEP_INTERVAL 150000000 // 0.15 seconds in nanoseconds

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN1, PI_OUTPUT) < 0 ||
        gpioSetMode(PWM_PIN2, PI_OUTPUT) < 0 ||
        gpioSetMode(PWM_PIN3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioHardwarePWM(PWM_PIN1, PWM_FREQUENCY, PWM_DUTY_CYCLE * PWM_FREQUENCY / 255) < 0 ||
        gpioHardwarePWM(PWM_PIN2, PWM_FREQUENCY, PWM_DUTY_CYCLE * PWM_FREQUENCY / 255) < 0 ||
        gpioHardwarePWM(PWM_PIN3, PWM_FREQUENCY, PWM_DUTY_CYCLE * PWM_FREQUENCY / 255) < 0) {
        fprintf(stderr, "Failed to set PWM on GPIO pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("PWM output started on GPIO pins %d, %d, %d\n", PWM_PIN1, PWM_PIN2, PWM_PIN3);

    while (keep_running) {
        printf("PWM state: ON\n");
        usleep(SLEEP_INTERVAL / 1000);
        printf("PWM state: OFF\n");
        usleep(SLEEP_INTERVAL / 1000);
    }

    gpioSetPWMdutycycle(PWM_PIN1, 0);
    gpioSetPWMdutycycle(PWM_PIN2, 0);
    gpioSetPWMdutycycle(PWM_PIN3, 0);

    gpioTerminate();
    printf("PWM output stopped and GPIO resources released\n");

    return EXIT_SUCCESS;
}

