#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define OPT3001_ADDR 0x44
#define I2C_BUS "/dev/i2c-1"

static int i2c_fd;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_msg messages[2];
    __u8 write_buf[2] = {0x00, 0x10}; // Command to start one-shot conversion
    __u8 read_buf[2];

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, OPT3001_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    messages[0].addr = OPT3001_ADDR;
    messages[0].flags = 0;
    messages[0].len = 2;
    messages[0].buf = write_buf;

    messages[1].addr = OPT3001_ADDR;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 2;
    messages[1].buf = read_buf;

    if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
        perror("Failed to communicate with OPT3001");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    float lux = (read_buf[0] << 4) | (read_buf[1] >> 4);
    lux *= 0.01; // Convert to lux

    printf("Lux: %.2f\n", lux);

    close(i2c_fd);
    return EXIT_SUCCESS;
}

