#define GPIO_PIN 17
#define INTERVAL_SECONDS 0.5

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile bool running = true;

void signal_handler(int signum) {
    running = false;
}

int main() {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int state = 0;
    while (running) {
        ret = gpiod_line_set_value(line, state);
        if (ret < 0) {
            perror("Failed to set GPIO line value");
        } else {
            printf("GPIO %d set to %d\n", GPIO_PIN, state);
        }

        state = !state;  // Toggle state
        sleep(INTERVAL_SECONDS);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

