    }

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUDRATE B115200
#define TIMEOUT_SEC 5

static int serial_fd = -1;

void cleanup(int signum) {
    if (serial_fd != -1) {
        close(serial_fd);
    }
    exit(EXIT_FAILURE);
}

int main() {
    struct termios tty;
    char buffer[256];
    ssize_t bytes_read;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    serial_fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (serial_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SERIAL_PORT, strerror(errno));
        return EXIT_FAILURE;
    }

    if (tcgetattr(serial_fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(serial_fd);
        return EXIT_FAILURE;
    }

    cfsetospeed(&tty, BAUDRATE);
    cfsetispeed(&tty, BAUDRATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_iflag &= ~IGNBRK;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (tcsetattr(serial_fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(serial_fd);
        return EXIT_FAILURE;
    }

    fd_set read_fds;
    struct timeval tv;

    while (1) {
        FD_ZERO(&read_fds);
        FD_SET(serial_fd, &read_fds);
        tv.tv_sec = TIMEOUT_SEC;
        tv.tv_usec = 0;

        int select_result = select(serial_fd + 1, &read_fds, NULL, NULL, &tv);
        if (select_result == -1) {
            fprintf(stderr, "Error from select: %s\n", strerror(errno));
            close(serial_fd);
            return EXIT_FAILURE;
        } else if (select_result == 0) {
            fprintf(stderr, "Timeout waiting for data\n");
            close(serial_fd);
            return EXIT_FAILURE;
        }

        bytes_read = read(serial_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read < 0) {
            fprintf(stderr, "Error from read: %s\n", strerror(errno));
            close(serial_fd);
            return EXIT_FAILURE;
        } else if (bytes_read == 0) {
            fprintf(stderr, "Device disconnected\n");
            close(serial_fd);
            return EXIT_FAILURE;
        }

        buffer[bytes_read] = '\0';
        printf("Received: %s", buffer);
        break;
    }

    close(serial_fd);
    return EXIT_SUCCESS;
}

