#define W1_BASE_PATH "/sys/bus/w1/devices"
#define W1_SLAVE_FILE "w1_slave"
#define GPIO_PIN 4
#define W1_GPIO_PIN 17
#define W1_GPIO_PIN2 18
#define SAMPLE_INTERVAL 5

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int read_temperature(const char *device_path) {
    char path[256];
    char buffer[256];
    int fd, ret;
    float temperature;

    snprintf(path, sizeof(path), "%s/%s/%s", W1_BASE_PATH, device_path, W1_SLAVE_FILE);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open w1 slave file");
        return -1;
    }

    ret = read(fd, buffer, sizeof(buffer) - 1);
    if (ret < 0) {
        perror("Failed to read w1 slave file");
        close(fd);
        return -1;
    }
    buffer[ret] = '\0';
    close(fd);

    char *pos = strstr(buffer, "t=");
    if (!pos) {
        fprintf(stderr, "Invalid temperature reading\n");
        return -1;
    }

    temperature = atof(pos + 2) / 1000.0;
    return (int)(temperature * 1000);  // Return temperature in millidegrees
}

int main() {
    struct dirent *entry;
    DIR *dp;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    dp = opendir(W1_BASE_PATH);
    if (!dp) {
        perror("Failed to open w1 base directory");
        return EXIT_FAILURE;
    }

    char *device_path = NULL;
    while ((entry = readdir(dp))) {
        if (strncmp(entry->d_name, "28-", 3) == 0) {
            device_path = entry->d_name;
            break;
        }
    }
    closedir(dp);

    if (!device_path) {
        fprintf(stderr, "DS18B20 device not found\n");
        return EXIT_FAILURE;
    }

    printf("Found DS18B20 device: %s\n", device_path);

    while (keep_running) {
        int temperature = read_temperature(device_path);
        if (temperature < -55000 || temperature > 125000) {
            fprintf(stderr, "Invalid temperature reading: %d\n", temperature);
        } else {
            printf("Temperature: %d.%03d°C\n", temperature / 1000, abs(temperature) % 1000);
        }
        sleep(SAMPLE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

