#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define I2C_SLAVE_FORCE 0x0706

// Function prototypes
int setup_i2c_connection(void);
int read_htu21d(int fd);
void cleanup(int signum);

int main() {
    int fd = setup_i2c_connection();
    if (fd < 0) {
        fprintf(stderr, "Error: Unable to open I2C bus\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        int temperature = read_htu21d(fd);
        if (temperature < 0) {
            fprintf(stderr, "Error: Failed to read temperature\n");
            cleanup(0);
            return EXIT_FAILURE;
        }
        printf("Temperature: %d°C\n", temperature);
        sleep(60);
    }

    return EXIT_SUCCESS;
}

int setup_i2c_connection(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE_FORCE, HTU21D_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int read_htu21d(int fd) {
    unsigned char buf[3];
    buf[0] = 0xE3; // Temperature command

    if (write(fd, buf, 1) != 1) {
        perror("Error writing to HTU21D");
        return -1;
    }

    usleep(50000); // Wait for conversion

    if (read(fd, buf, 3) != 3) {
        perror("Error reading from HTU21D");
        return -1;
    }

    unsigned int raw_temp = ((buf[0] << 8) | buf[1]) & 0xFFFC;
    int temperature = -46.85 + 175.72 * (float)raw_temp / 65536.0;

    if (temperature < -40 || temperature > 125) {
        fprintf(stderr, "Error: Invalid temperature reading\n");
        return -1;
    }

    return (int)temperature;
}

void cleanup(int signum) {
    printf("\nExiting...\n");
    exit(EXIT_SUCCESS);
}

