#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT_PIN 17
#define RETRY_COUNT 5
#define RETRY_DELAY_MS 1000

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int retries = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Unable to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT_PIN);
    if (!line) {
        fprintf(stderr, "Error: Unable to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int err = gpiod_line_request_input(line, "DHT22");
        if (err < 0) {
            if (retries < RETRY_COUNT) {
                fprintf(stderr, "Error: Unable to request GPIO line, retrying...\n");
                usleep(RETRY_DELAY_MS * 1000);
                retries++;
                continue;
            } else {
                fprintf(stderr, "Error: Unable to request GPIO line after %d retries\n", RETRY_COUNT);
                break;
            }
        }

        retries = 0;

        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error: Unable to read GPIO line value\n");
            break;
        }

        printf("GPIO %d state: %s\n", DHT_PIN, value ? "HIGH" : "LOW");

        gpiod_line_release(line);
        sleep(2);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

