#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDR 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATAL 0x14
#define TCS34725_CDATAH 0x15

int i2c_fd;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

int write_i2c(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, 2);
}

int read_i2c(int fd, uint8_t reg, uint8_t *value, int len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, value, len);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, TCS34725_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Enable the device
    if (write_i2c(i2c_fd, TCS34725_ENABLE, 0x01) < 0) {
        perror("Failed to enable TCS34725");
        cleanup(1);
    }

    // Set integration time to 2.4ms
    if (write_i2c(i2c_fd, TCS34725_ATIME, 0xFF) < 0) {
        perror("Failed to set integration time");
        cleanup(1);
    }

    // Set gain to 1x
    if (write_i2c(i2c_fd, TCS34725_CONTROL, 0x00) < 0) {
        perror("Failed to set gain");
        cleanup(1);
    }

    struct timespec delay = {0, 200000000}; // 0.2 seconds

    while (1) {
        uint8_t data[6];
        if (read_i2c(i2c_fd, TCS34725_CDATAL | TCS34725_COMMAND_BIT, data, 6) < 0) {
            perror("Failed to read from TCS34725");
            cleanup(1);
        }

        uint16_t r = data[1] << 8 | data[0];
        uint16_t g = data[3] << 8 | data[2];
        uint16_t b = data[5] << 8 | data[4];

        printf("R: %d, G: %d, B: %d\n", r, g, b);

        nanosleep(&delay, NULL);
    }

    return 0;
}

