#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_22 22
#define GPIO_PIN_27 27
#define INTERVAL_US 10000 // 0.01 seconds

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line22, *line27;
    int ret;

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Request lines
    line22 = gpiod_chip_get_line(chip, GPIO_PIN_22);
    line27 = gpiod_chip_get_line(chip, GPIO_PIN_27);

    if (!line22 || !line27) {
        fprintf(stderr, "Error getting GPIO lines\n");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    ret = gpiod_line_request_output(line22, "output22", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO_PIN_22, strerror(-ret));
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    ret = gpiod_line_request_output(line27, "output27", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO_PIN_27, strerror(-ret));
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    // Main loop
    int state22 = 0, state27 = 0;
    while (keep_running) {
        // Toggle states
        state22 = !state22;
        state27 = !state27;

        // Set GPIO values
        gpiod_line_set_value(line22, state22);
        gpiod_line_set_value(line27, state27);

        // Report state
        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_22, state22, GPIO_PIN_27, state27);

        // Sleep
        usleep(INTERVAL_US);
    }

cleanup:
    // Release resources
    if (line22) gpiod_line_release(line22);
    if (line27) gpiod_line_release(line27);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

