#define I2C_BUS "/dev/i2c-1"
#define SSD1306_I2C_ADDR 0x3C
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64

static int i2c_fd;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int write_command(unsigned char cmd) {
    unsigned char buf[2] = {0x00, cmd};
    return write(i2c_fd, buf, sizeof(buf));
}

int write_data(unsigned char data) {
    unsigned char buf[2] = {0x40, data};
    return write(i2c_fd, buf, sizeof(buf));
}

void init_display() {
    write_command(0xAE); // Display off
    write_command(0x20); // Set memory addressing mode
    write_command(0x10); // 00,Horizontal Addressing Mode;01,Vertical Addressing Mode;10,Page Addressing Mode (RESET);11,Invalid
    write_command(0xB0); // Set Page Start Address for Page Addressing Mode,0-7
    write_command(0xC8); // Set COM Output Scan Direction
    write_command(0x00); // ---set low column address
    write_command(0x10); // ---set high column address
    write_command(0x40); // --set start line address
    write_command(0x81); // --set contrast control register
    write_command(0xFF); //亮度 0x00~0xFF
    write_command(0xA1); // --set segment re-map 0 to 127
    write_command(0xA6); // --set normal display
    write_command(0xA8); // --set multiplex ratio(1 to 64)
    write_command(0x3F); //
    write_command(0xA4); // 0xa4,Output follows RAM content;0xa5,Output ignores RAM content
    write_command(0xD3); // -set display offset
    write_command(0x00); // -not offset
    write_command(0xD5); // --set display clock divide ratio/oscillator frequency
    write_command(0xF0); // --set divide ratio
    write_command(0xD9); // --set pre-charge period
    write_command(0x22); //
    write_command(0xDA); // --set com pins hardware configuration
    write_command(0x12);
    write_command(0xDB); // --set vcomh
    write_command(0x20); // 0x20,0.77xVcc
    write_command(0x8D); // --set DC-DC enable
    write_command(0x14); //
    write_command(0xAF); // --turn on oled panel
}

void clear_display() {
    for (int i = 0; i < 8; i++) {
        write_command(0xB0 + i);
        write_command(0x00);
        write_command(0x10);
        for (int j = 0; j < SCREEN_WIDTH; j++) {
            write_data(0x00);
        }
    }
}

void display_text(const char *text) {
    clear_display();
    int len = strlen(text);
    if (len > SCREEN_WIDTH) len = SCREEN_WIDTH;

    for (int i = 0; i < len; i++) {
        write_command(0xB0);
        write_command(0x00 + (i % SCREEN_WIDTH));
        write_command(0x10);
        write_data(text[i]);
    }
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    init_display();

    char buffer[256];
    while (1) {
        snprintf(buffer, sizeof(buffer), "Temp: %.2fC", 25.5); // Example temperature
        display_text(buffer);
        usleep(100000); // 0.1 seconds
    }

    return EXIT_SUCCESS;
}

