void cleanup(int signum) {
    keep_running = 0;
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int measure_distance() {
    struct timespec start, end;
    long elapsed_ns;

    gpiod_line_set_value(trigger_line, 1);
    usleep(10);  // 10 microseconds
    gpiod_line_set_value(trigger_line, 0);

    clock_gettime(CLOCK_MONOTONIC, &start);

    int echo_state = gpiod_line_get_value(echo_line);
    while (echo_state == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
            perror("clock_gettime");
            return -1;
        }
        elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000) {
            fprintf(stderr, "Timeout waiting for echo\n");
            return -1;
        }
        echo_state = gpiod_line_get_value(echo_line);
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (echo_state == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
            perror("clock_gettime");
            return -1;
        }
        elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000) {
            fprintf(stderr, "Timeout waiting for echo to end\n");
            return -1;
        }
        echo_state = gpiod_line_get_value(echo_line);
    }

    elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
    return (int)(elapsed_ns / 58);  // Speed of sound ~343 m/s, so distance = time * 34300 / 2
}

