        clock_gettime(CLOCK_MONOTONIC, &start);

        int reading = read_sensor();
        if (is_valid_reading(reading)) {
            MQTTClient_message pubmsg = MQTTClient_message_initializer;
            pubmsg.payload = malloc(20);
            snprintf(pubmsg.payload, 20, "%d", reading);
            pubmsg.payloadlen = strlen(pubmsg.payload);
            pubmsg.qos = QOS0;
            pubmsg.retained = 0;

            MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, NULL);
            free(pubmsg.payload);
        }

        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;

        if (elapsed < READ_INTERVAL_MS) {
            usleep((READ_INTERVAL_MS - elapsed) * 1000);
        }
    }

    MQTTClient_disconnect(client, 10000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return 0;
}

