#define MAX_DISTANCE_CM 400
#define MIN_DISTANCE_CM 2
#define TIMEOUT_US 30000
#define INTERVAL_MS 100

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

bool is_valid_distance(int distance) {
    return distance >= MIN_DISTANCE_CM && distance <= MAX_DISTANCE_CM;
}

int measure_distance(struct gpiod_chip *chip, int trig, int echo) {
    struct gpiod_line *trig_line = gpiod_chip_get_line(chip, trig);
    struct gpiod_line *echo_line = gpiod_chip_get_line(chip, echo);

    if (!trig_line || !echo_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        return -1;
    }

    gpiod_line_request_output(trig_line, "HC-SR04-TRIG", 0);
    gpiod_line_request_input(echo_line, "HC-SR04-ECHO");

    gpiod_line_set_value(trig_line, 1);
    usleep(10);
    gpiod_line_set_value(trig_line, 0);

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    int timeout = 0;
    while (gpiod_line_get_value(echo_line) == 0) {
        if (timeout++ > TIMEOUT_US / 10) {
            fprintf(stderr, "Echo pulse not received\n");
            gpiod_line_release(trig_line);
            gpiod_line_release(echo_line);
            return -1;
        }
        usleep(10);
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    long elapsed = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);

    if (elapsed > TIMEOUT_US) {
        fprintf(stderr, "Echo pulse too long\n");
        return -1;
    }

    int distance = (int)(elapsed / 58.0);
    return is_valid_distance(distance) ? distance : -1;
}

