    keep_running = 0;
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int measure_distance() {
    struct timespec start, end;
    long elapsed_ns;

    // Send 10us pulse to trigger
    gpiod_line_set_value(trigger_line, 1);
    nanosleep(&(struct timespec){0, 10000}, NULL);
    gpiod_line_set_value(trigger_line, 0);

    // Wait for echo to go high
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        if ((elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + 
                           (end.tv_nsec - start.tv_nsec)) > TIMEOUT_US * 1000) {
            return -1;  // Timeout
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
    }

    // Measure high time
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 1) {
        if ((elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + 
                           (end.tv_nsec - start.tv_nsec)) > TIMEOUT_US * 1000) {
            return -1;  // Timeout
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
    }

    // Calculate distance (in cm)
    long echo_time_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + 
                        (end.tv_nsec - start.tv_nsec);
    return (int)(echo_time_ns / 58.0);  // Speed of sound ~343m/s = 34300cm/s
}

