#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <Adafruit_ADS1015.h>
#include <MQTTClient.h>

#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_CLIENT_ID "ads1115_publisher"
#define MQTT_TOPIC "sensors/ads1115"
#define NUM_READINGS 10
#define SAMPLE_INTERVAL_MS 1000

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    Adafruit_ADS1015 ads;
    if (ads.begin() != 0) {
        fprintf(stderr, "Failed to initialize ADS1115\n");
        gpioTerminate();
        return 1;
    }

    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc;

    MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID,
                      MQTTCLIENT_PERSISTENCE_NONE, NULL);

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        ads.end();
        gpioTerminate();
        MQTTClient_destroy(&client);
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    for (int i = 0; i < NUM_READINGS && keep_running; i++) {
        int16_t adc0 = ads.readADC_SingleEnded(0);
        if (adc0 < -32768 || adc0 > 32767) {
            fprintf(stderr, "ADC value out of range: %d\n", adc0);
            continue;
        }

        char payload[20];
        snprintf(payload, sizeof(payload), "%d", adc0);

        MQTTClient_message pubmsg = MQTTClient_message_initializer;
        pubmsg.payload = payload;
        pubmsg.payloadlen = strlen(payload);
        pubmsg.qos = QOS0;
        pubmsg.retained = 0;

        MQTTClient_deliveryToken token;
        if ((rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token)) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        } else {
            printf("Published: %s\n", payload);
        }

        MQTTClient_waitForCompletion(client, token, 1000);
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    ads.end();
    gpioTerminate();

    return 0;
}

