#include <signal.h>
#include <errno.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B115200

static int serial_fd = -1;

void cleanup(int signum) {
    if (serial_fd != -1) {
        tcsetattr(serial_fd, TCSANOW, NULL);
        close(serial_fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct termios tty;
    char buffer[256];
    ssize_t bytes_read;

    // Open the serial port
    serial_fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (serial_fd < 0) {
        perror("Error opening serial port");
        return EXIT_FAILURE;
    }

    // Configure the serial port
    if (tcgetattr(serial_fd, &tty) != 0) {
        perror("Error from tcgetattr");
        close(serial_fd);
        return EXIT_FAILURE;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;                         // Disable break processing
    tty.c_lflag = 0;                                // Raw input
    tty.c_oflag = 0;                                // Raw output
    tty.c_cc[VMIN] = 0;                             // Read doesn't block
    tty.c_cc[VTIME] = 5;                            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);         // Turn off s/w flow ctrl
    tty.c_cflag |= (CLOCAL | CREAD);                // Ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD);              // Turn off parity
    tty.c_cflag &= ~CSTOPB;                         // Use only one stop bit

    if (tcsetattr(serial_fd, TCSANOW, &tty) != 0) {
        perror("Error from tcsetattr");
        close(serial_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler for cleanup
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Read and print data
    while (1) {
        bytes_read = read(serial_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s", buffer);
        } else if (bytes_read == 0) {
            printf("Connection closed by remote host\n");
            break;
        } else {
            perror("Error reading from serial port");
            break;
        }
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

