#define MPU6050_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"
#define I2C_SLAVE_FORCE 0x0706
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int file, ret;
    char buf[14];
    short accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    struct i2c_msg messages[1];
    struct i2c_rdwr_ioctl_data packets;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    file = open(I2C_BUS, O_RDWR);
    if (file < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE_FORCE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return EXIT_FAILURE;
    }

    buf[0] = MPU6050_PWR_MGMT_1;
    buf[1] = 0;
    if (write(file, buf, 2) != 2) {
        perror("Failed to write to the I2C bus");
        close(file);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        messages[0].addr = MPU6050_ADDR;
        messages[0].flags = 0;
        messages[0].len = 14;
        messages[0].buf = buf;

        packets.msgs = messages;
        packets.nmsgs = 1;

        if (ioctl(file, I2C_RDWR, &packets) < 0) {
            perror("Failed to read from the I2C bus");
            close(file);
            return EXIT_FAILURE;
        }

        accel_x = (buf[0] << 8) | buf[1];
        accel_y = (buf[2] << 8) | buf[3];
        accel_z = (buf[4] << 8) | buf[5];
        gyro_x = (buf[8] << 8) | buf[9];
        gyro_y = (buf[10] << 8) | buf[11];
        gyro_z = (buf[12] << 8) | buf[13];

        printf("Accel: X=%d Y=%d Z=%d | Gyro: X=%d Y=%d Z=%d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        usleep(100000);  // 0.1 seconds
    }

    close(file);
    return EXIT_SUCCESS;
}

