    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %d\n", rc);
        cleanup(0);
    }

    // Read sensor and publish
    int sensor_value = gpiod_line_get_value(line);
    char payload[20];
    snprintf(payload, sizeof(payload), "%d", sensor_value);

    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = QOS0;
    pubmsg.retained = 0;

    rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %d\n", rc);
    } else {
        printf("Published sensor reading: %s\n", payload);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_PINS 5
const int pins[NUM_PINS] = {2, 3, 18, 23, 24};

void cleanup(int signum) {
    for (int i = 0; i < NUM_PINS; i++) {
        gpioSetMode(pins[i], PI_INPUT);
        gpioWrite(pins[i], 0);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Unable to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: Unable to set mode for GPIO %d\n", pins[i]);
            cleanup(0);
        }
        if (gpioSetPWMfrequency(pins[i], 1000) < 0) {
            fprintf(stderr, "Error: Unable to set PWM frequency for GPIO %d\n", pins[i]);
            cleanup(0);
        }
        if (gpioPWM(pins[i], 128) < 0) {
            fprintf(stderr, "Error: Unable to set PWM duty cycle for GPIO %d\n", pins[i]);
            cleanup(0);
        }
        printf("GPIO %d set to PWM with 50%% duty cycle\n", pins[i]);
    }

    sleep(1);  // Run for 1 second

    cleanup(0);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN1 17
#define PWM_PIN2 22
#define PWM_PIN3 27
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 128  // 50% duty cycle
#define INTERVAL_MS 50

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(PWM_PIN1, PI_OUTPUT);
    gpioSetMode(PWM_PIN2, PI_OUTPUT);
    gpioSetMode(PWM_PIN3, PI_OUTPUT);

    gpioSetPWMfrequency(PWM_PIN1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN3, PWM_FREQUENCY);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        gpioPWM(PWM_PIN1, PWM_DUTY_CYCLE);
        gpioPWM(PWM_PIN2, PWM_DUTY_CYCLE);
        gpioPWM(PWM_PIN3, PWM_DUTY_CYCLE);

        printf("PWM applied to GPIO %d, %d, %d\n", PWM_PIN1, PWM_PIN2, PWM_PIN3);

        time_sleep(INTERVAL_MS / 1000.0);
    }

    gpioSetPWMdutycycle(PWM_PIN1, 0);
    gpioSetPWMdutycycle(PWM_PIN2, 0);
    gpioSetPWMdutycycle(PWM_PIN3, 0);

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 3 / 2)

static int fd = -1;
static void *buffer = NULL;

void cleanup(int signum) {
    if (buffer) {
        munmap(buffer, IMAGE_SIZE);
    }
    if (fd != -1) {
        close(fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    int ret;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    fd = open(DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open video device");
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret == -1) {
        perror("Failed to set format");
        goto error;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret == -1) {
        perror("Failed to request buffers");
        goto error;
    }

    buffer = mmap(NULL, IMAGE_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Failed to map buffer");
        goto error;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    ret = ioctl(fd, VIDIOC_QBUF, &buf);
    if (ret == -1) {
        perror("Failed to queue buffer");
        goto error;
    }

    ret = ioctl(fd, VIDIOC_STREAMON, &req.type);
    if (ret == -1) {
        perror("Failed to start streaming");
        goto error;
    }

    while (1) {
        fd_set fds;
        struct timeval tv;
        int r;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 1;
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (r == -1) {
            perror("Select failed");
            goto error;
        }

        if (r == 0) {
            fprintf(stderr, "Timeout occurred\n");
            continue;
        }

        ret = read(fd, buffer, IMAGE_SIZE);
        if (ret == -1) {
            perror("Failed to read from device");
            goto error;
        }

        char filename[256];
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        snprintf(filename, sizeof(filename), "image_%04d%02d%02d_%02d%02d%02d.jpg",
                 t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                 t->tm_hour, t->tm_min, t->tm_sec);

        FILE *file = fopen(filename, "wb");
        if (!file) {
            perror("Failed to open file for writing");
            goto error;
        }

        fwrite(buffer, 1, ret, file);
        fclose(file);

        printf("Image saved as %s\n", filename);

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = 0;

        ret = ioctl(fd, VIDIOC_QBUF, &buf);
        if (ret == -1) {
            perror("Failed to requeue buffer");
            goto error;
        }
    }

error:
    cleanup(0);
    return EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>

#define CAMERA_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_MJPEG

void cleanup(int fd, void *buffer) {
    if (buffer) {
        munmap(buffer, IMAGE_WIDTH * IMAGE_HEIGHT * 3 / 2);
    }
    if (fd >= 0) {
        close(fd);
    }
}

int main() {
    int fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open camera device");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        cleanup(fd, NULL);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        cleanup(fd, NULL);
        return EXIT_FAILURE;
    }

    void *buffer = mmap(NULL, IMAGE_WIDTH * IMAGE_HEIGHT * 3 / 2,
                        PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Failed to map buffer");
        cleanup(fd, NULL);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        cleanup(fd, buffer);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Failed to queue buffer");
        cleanup(fd, buffer);
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start streaming");
        cleanup(fd, buffer);
        return EXIT_FAILURE;
    }

    fd_set fds;
    struct timeval tv;
    int ret;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    ret = select(fd + 1, &fds, NULL, NULL, &tv);
    if (ret < 0) {
        perror("Select failed");
        cleanup(fd, buffer);
        return EXIT_FAILURE;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout: No frame captured\n");
        cleanup(fd, buffer);
        return EXIT_FAILURE;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Failed to dequeue buffer");
        cleanup(fd, buffer);
        return EXIT_FAILURE;
    }

    FILE *file = fopen("captured_image.jpg", "wb");
    if (!file) {
        perror("Failed to open output file");
        cleanup(fd, buffer);
        return EXIT_FAILURE;
    }

    if (fwrite(buffer, buf.bytesused, 1, file) != 1) {
        perror("Failed to write image to file");
        fclose(file);
        cleanup(fd, buffer);
        return EXIT_FAILURE;
    }

    fclose(file);

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Failed to stop streaming");
    }

    cleanup(fd, buffer);
    return EXIT_SUCCESS;
}

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_2 2
#define GPIO_PIN_3 3
#define INTERVAL_SECONDS 0.5

static struct gpiod_chip *chip;
static struct gpiod_line *line2;
static struct gpiod_line *line3;

void cleanup(int signum) {
    if (line2) {
        gpiod_line_release(line2);
    }
    if (line3) {
        gpiod_line_release(line3);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Request lines for GPIO 2 and GPIO 3
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        fprintf(stderr, "Error getting line for GPIO %d: %s\n", GPIO_PIN_2, strerror(errno));
        goto error;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!line3) {
        fprintf(stderr, "Error getting line for GPIO %d: %s\n", GPIO_PIN_3, strerror(errno));
        goto error;
    }

    // Request the lines as outputs
    ret = gpiod_line_request_output(line2, "output2", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n", GPIO_PIN_2, strerror(-ret));
        goto error;
    }

    ret = gpiod_line_request_output(line3, "output3", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n", GPIO_PIN_3, strerror(-ret));
        goto error;
    }

    // Set up signal handler for clean exit
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Main loop
    int state = 0;
    while (1) {
        // Set GPIO 2 and GPIO 3 to the current state
        gpiod_line_set_value(line2, state);
        gpiod_line_set_value(line3, state);

        // Report the state
        printf("GPIO 2: %d, GPIO 3: %d\n", state, state);

        // Toggle the state
        state = !state;

        // Wait for the specified interval
        sleep(INTERVAL_SECONDS);
    }

error:
    cleanup(0);
    return EXIT_FAILURE;
}

