        return EXIT_FAILURE;
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the line as an output
    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler for clean exit
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    int state = 0;
    while (1) {
        // Set the GPIO line to the current state
        ret = gpiod_line_set_value(line, state);
        if (ret < 0) {
            perror("Failed to set GPIO line value");
            cleanup(0);
