#define DHT_PIN 4
#define MAX_RETRIES 5
#define TIMEOUT_US 85

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int read_dht22(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Failed to get line\n");
        return -1;
    }

    int ret = gpiod_line_request_input(line, "DHT22");
    if (ret < 0) {
        fprintf(stderr, "Failed to request line as input\n");
        gpiod_line_release(line);
        return -1;
    }

    int data[5] = {0};
    int bit_count = 0;
    int byte_count = 0;
    int last_state = 1;
    int bits = 0;
    int retries = 0;

    while (keep_running && retries < MAX_RETRIES) {
        bits = 0;
        for (int i = 0; i < 40; i++) {
            int state = gpiod_line_get_value(line);
            if (state == -1) {
                fprintf(stderr, "Failed to read line value\n");
                gpiod_line_release(line);
                return -1;
            }

            if (state != last_state) {
                bit_count++;
                last_state = state;
            } else {
                bit_count = 0;
            }

            if (bit_count > TIMEOUT_US) {
                break;
            }

            if (bit_count > 10) {
                bits = (bits << 1) | state;
                if (i % 8 == 7) {
                    data[byte_count++] = bits;
                    bits = 0;
                }
            }
        }

        if (byte_count == 5) {
            unsigned int checksum = (unsigned int)data[0] + data[1] + data[2] + data[3];
            if (checksum == data[4]) {
                printf("Temperature: %.1f°C, Humidity: %.1f%%\n", 
                       (float)data[2] + (float)data[3] / 10.0, 
                       (float)data[0] + (float)data[1] / 10.0);
                gpiod_line_release(line);
                return 0;
            }
        }

        retries++;
        usleep(200000);  // Wait 200ms before retrying
    }

    fprintf(stderr, "Failed to read valid data from DHT22\n");
    gpiod_line_release(line);
    return -1;
}

int main() {
    struct gpiod_chip *chip;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    ret = read_dht22(chip, DHT_PIN);

    gpiod_chip_close(chip);
    return ret == 0 ? EXIT_SUCCESS : EXIT_FAILURE;
}

