#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MCP3008_CLK  18
#define MCP3008_MISO 23
#define MCP3008_MOSI 24
#define MCP3008_CS   25
#define MCP3008_CH   0
#define MQTT_BROKER  "localhost"
#define MQTT_PORT    1883
#define MQTT_TOPIC   "sensor/mcp3008"

static volatile int keep_running = 1;
static struct mosquitto *mosq = NULL;

void cleanup(int signum) {
    keep_running = 0;
    if (mosq) {
        mosquitto_destroy(mosq);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int mcp3008_read(int channel) {
    int adc = 0;
    gpioWrite(MCP3008_CLK, 0);
    gpioWrite(MCP3008_CS, 0);

    gpioWrite(MCP3008_MOSI, 1);  // Start bit
    gpioSleep(1, 0, 1);
    gpioWrite(MCP3008_MOSI, 1);  // Single-ended
    gpioSleep(1, 0, 1);

    for (int i = 7; i >= 0; i--) {
        gpioWrite(MCP3008_MOSI, (channel >> i) & 0x01);
        gpioSleep(1, 0, 1);
        gpioWrite(MCP3008_CLK, 1);
        gpioSleep(1, 0, 1);
        gpioWrite(MCP3008_CLK, 0);
        gpioSleep(1, 0, 1);
    }

    for (int i = 19; i >= 0; i--) {
        gpioWrite(MCP3008_CLK, 1);
        gpioSleep(1, 0, 1);
        gpioWrite(MCP3008_CLK, 0);
        gpioSleep(1, 0, 1);
        adc <<= 1;
        if (gpioRead(MCP3008_MISO)) {
            adc++;
        }
    }

    gpioWrite(MCP3008_CS, 1);
    return adc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(MCP3008_CLK, PI_OUTPUT);
    gpioSetMode(MCP3008_MOSI, PI_OUTPUT);
    gpioSetMode(MCP3008_MISO, PI_INPUT);
    gpioSetMode(MCP3008_CS, PI_OUTPUT);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating Mosquitto instance\n");
        cleanup(0);
    }

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Unable to connect to MQTT broker\n");
        cleanup(0);
    }

    int adc_value = mcp3008_read(MCP3008_CH);
    char payload[10];
    snprintf(payload, sizeof(payload), "%d", adc_value);

    if (mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message\n");
    }

    mosquitto_disconnect(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>

#define CAMERA_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT V4L2_PIX_FMT_MJPEG

void error_exit(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int main() {
    int fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error: %s not found or unable to open.\n", CAMERA_DEVICE);
        exit(EXIT_FAILURE);
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        error_exit("VIDIOC_QUERYCAP");
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device.\n", CAMERA_DEVICE);
        close(fd);
        exit(EXIT_FAILURE);
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = IMAGE_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        error_exit("VIDIOC_S_FMT");
    }

    unsigned int n_buffers = 4;
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = n_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        error_exit("VIDIOC_REQBUFS");
    }

    struct v4l2_buffer buf;
    for (unsigned int i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            error_exit("VIDIOC_QUERYBUF");
        }

        void *mem = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (mem == MAP_FAILED) {
            error_exit("mmap");
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            error_exit("VIDIOC_QBUF");
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        error_exit("VIDIOC_STREAMON");
    }

    fd_set fds;
    struct timeval tv;
    int ret;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    while (1) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        ret = select(fd + 1, &fds, NULL, NULL, &tv);

        if (ret == -1) {
            if (errno == EINTR) {
                continue;
            }
            error_exit("select");
        }

        if (ret == 0) {
            fprintf(stderr, "Timeout: No frame captured.\n");
            break;
        }

        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            error_exit("VIDIOC_DQBUF");
        }

        FILE *file = fopen("captured_image.jpg", "wb");
        if (!file) {
            error_exit("fopen");
        }

        if (fwrite(mem, buf.bytesused, 1, file) != 1) {
            error_exit("fwrite");
        }

        fclose(file);

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            error_exit("VIDIOC_QBUF");
        }
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        error_exit("VIDIOC_STREAMOFF");
    }

    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (munmap(mem, buf.length) == -1) {
            error_exit("munmap");
        }
    }

    close(fd);
    return 0;
}

