    int i, ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    line17 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    line18 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!line17 || !line18) {
        perror("Failed to get GPIO lines");
        cleanup(0);
    }

    // Request lines as outputs
    ret = gpiod_line_request_output(line17, "output17", 0);
    if (ret < 0) {
        perror("Failed to request line 17 as output");
        cleanup(0);
    }
    ret = gpiod_line_request_output(line18, "output18", 0);
    if (ret < 0) {
        perror("Failed to request line 18 as output");
        cleanup(0);
    }

    // Set up signal handler for cleanup
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Main loop for 3 cycles
    for (i = 0; i < NUM_CYCLES; i++) {
        // Set both pins high
        gpiod_line_set_value(line17, 1);
        gpiod_line_set_value(line18, 1);
        printf("Cycle %d: Both pins HIGH\n", i + 1);
        usleep(DELAY_MS * 1000);

        // Set pin 17 low, pin 18 high
        gpiod_line_set_value(line17, 0);
        gpiod_line_set_value(line18, 1);
        printf("Cycle %d: Pin 17 LOW, Pin 18 HIGH\n", i + 1);
        usleep(DELAY_MS * 1000);

        // Set both pins low
        gpiod_line_set_value(line17, 0);
        gpiod_line_set_value(line18, 0);
