#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x20
#define PCF8574_OUTPUT 0x00

static int i2c_fd;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int write_pcf8574(uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = PCF8574_OUTPUT;
    buffer[1] = value;

    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to PCF8574");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t value = 0;
    while (1) {
        if (write_pcf8574(value) < 0) {
            cleanup(0);
        }

        printf("Displaying value: %02X\n", value);

        value = (value + 1) & 0xFF;  // Keep value within 0-255 range
        usleep(500000);  // 0.5 seconds
    }

    return EXIT_SUCCESS;
}

