#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define GPIO_CHIP "gpiochip0"

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile sig_atomic_t keep_running = 1;

void cleanup(int signum) {
    keep_running = 0;
}

int setup_gpio() {
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!trigger_line || !echo_line) {
        fprintf(stderr, "Error getting GPIO lines\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "HC-SR04 Trigger", 0) < 0 ||
        gpiod_line_request_input(echo_line, "HC-SR04 Echo") < 0) {
        fprintf(stderr, "Error requesting GPIO lines\n");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void release_gpio() {
    if (trigger_line) gpiod_line_release(trigger_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
}

double measure_distance() {
    const int timeout_us = 30000; // 30ms timeout
    struct timespec start, end;
    long elapsed_us;

    gpiod_line_set_value(trigger_line, 1);
    usleep(10); // 10 microseconds
    gpiod_line_set_value(trigger_line, 0);

    clock_gettime(CLOCK_MONOTONIC, &start);

    int echo_value = 0;
    do {
        echo_value = gpiod_line_get_value(echo_line);
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    } while (echo_value == 0 && elapsed_us < timeout_us);

    if (echo_value == 0) {
        return -1; // Timeout
    }

    start = end;
    do {
        echo_value = gpiod_line_get_value(echo_line);
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    } while (echo_value == 1 && elapsed_us < timeout_us);

    if (echo_value == 1) {
        return -1; // Timeout
    }

    // Speed of sound is approximately 343 m/s or 29.1 m/us at room temperature
    // The distance is half the time taken for the sound to travel there and back
    return (elapsed_us / 2.0) * 0.0343;
}

int main() {
    if (setup_gpio() != 0) {
        fprintf(stderr, "Failed to setup GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (keep_running) {
        double distance = measure_distance();
        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            printf("Error measuring distance\n");
        }
        sleep(1);
    }

    release_gpio();
    return EXIT_SUCCESS;
}

