int main() {
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    int ret;
    char filename[256];
    time_t last_capture = 0;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    fd = open(DEVICE, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening video device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret == -1) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        goto error;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret == -1) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        goto error;
    }

    buffer = mmap(NULL, IMAGE_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        goto error;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    ret = ioctl(fd, VIDIOC_QBUF, &buf);
    if (ret == -1) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        goto error;
    }

    ret = ioctl(fd, VIDIOC_STREAMON, &req.type);
    if (ret == -1) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        goto error;
    }

    while (1) {
        time_t now = time(NULL);
        if (now - last_capture >= 1) {
            last_capture = now;

            memset(&buf, 0, sizeof(buf));
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;

            ret = read(fd, buffer, IMAGE_SIZE);
            if (ret == -1) {
                fprintf(stderr, "Error reading from device: %s\n", strerror(errno));
                goto error;
            }

            snprintf(filename, sizeof(filename), "image_%ld.jpg", now);
            FILE *file = fopen(filename, "wb");
            if (!file) {
                fprintf(stderr, "Error opening file for writing: %s\n", strerror(errno));
                goto error;
            }

            fwrite(buffer, 1, IMAGE_SIZE, file);
            fclose(file);

            printf("Captured image: %s\n", filename);
        }

        usleep(100000);  // Sleep for 100ms
    }

error:
    cleanup(0);
    return EXIT_FAILURE;
}

#include <stdio.h>
