#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x20
#define I2C_TIMEOUT 1000 // 1 second timeout

static int i2c_fd = -1;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_msg messages[1];
    struct i2c_rdwr_ioctl_data packets;
    char buffer[2];
    int ret;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    messages[0].addr = I2C_ADDR;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = buffer;

    packets.msgs = messages;
    packets.nmsgs = 1;

    for (int i = 0; i < 256; i++) {
        buffer[0] = i;

        ret = ioctl(i2c_fd, I2C_RDWR, &packets);
        if (ret < 0) {
            if (errno == ETIMEDOUT) {
                fprintf(stderr, "I2C device not responding, giving up\n");
                break;
            } else {
                perror("I2C transfer failed");
                break;
            }
        }

        printf("Displayed value: %d\n", i);
        usleep(100000); // 100ms delay between displays
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

