#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define PWM_PIN1 18
#define PWM_PIN2 23
#define PWM_PIN3 24
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define PWM_DURATION 100000 // 0.1 seconds in microseconds

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN1, PI_OUTPUT) < 0 ||
        gpioSetMode(PWM_PIN2, PI_OUTPUT) < 0 ||
        gpioSetMode(PWM_PIN3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN1, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(PWM_PIN2, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(PWM_PIN3, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        for (int duty = 0; duty <= PWM_RANGE; duty++) {
            if (!keep_running) break;

            gpioPWM(PWM_PIN1, duty);
            gpioPWM(PWM_PIN2, duty);
            gpioPWM(PWM_PIN3, duty);

            printf("PWM1: %d, PWM2: %d, PWM3: %d\n", duty, duty, duty);
            fflush(stdout);

            usleep(PWM_DURATION);
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define GPIO_CHIP "gpiochip0"
#define TIMEOUT_US 30000 // 30 ms timeout

void cleanup(struct gpiod_line *trigger_line, struct gpiod_line *echo_line, struct gpiod_chip *chip) {
    if (trigger_line) gpiod_line_release(trigger_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!trigger_line || !echo_line) {
        fprintf(stderr, "Error requesting GPIO lines\n");
        cleanup(trigger_line, echo_line, chip);
        return EXIT_FAILURE;
    }

    // Configure lines
    ret = gpiod_line_request_output(trigger_line, "hc_sr04_trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting trigger line as output\n");
        cleanup(trigger_line, echo_line, chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(echo_line, "hc_sr04_echo");
    if (ret < 0) {
        fprintf(stderr, "Error requesting echo line as input\n");
        cleanup(trigger_line, echo_line, chip);
        return EXIT_FAILURE;
    }

    // Trigger pulse
    gpiod_line_set_value(trigger_line, 1);
    usleep(10); // 10 microseconds
    gpiod_line_set_value(trigger_line, 0);

    // Wait for echo
    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);

    int echo_state = 0;
    while (echo_state == 0) {
        echo_state = gpiod_line_get_value(echo_line);
        clock_gettime(CLOCK_MONOTONIC, &current);

        // Check for timeout
        if ((current.tv_sec - start.tv_sec) * 1000000 + (current.tv_nsec - start.tv_nsec) / 1000 >= TIMEOUT_US) {
            fprintf(stderr, "Echo pulse not received within timeout\n");
            cleanup(trigger_line, echo_line, chip);
            return EXIT_FAILURE;
        }
    }

    // Measure echo pulse duration
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &current);

        // Check for timeout
        if ((current.tv_sec - start.tv_sec) * 1000000 + (current.tv_nsec - start.tv_nsec) / 1000 >= TIMEOUT_US) {
            fprintf(stderr, "Echo pulse too long\n");
            cleanup(trigger_line, echo_line, chip);
            return EXIT_FAILURE;
        }
    }

    // Calculate distance
    double duration_us = (current.tv_sec - start.tv_sec) * 1000000.0 + (current.tv_nsec - start.tv_nsec) / 1000.0;
    double distance_cm = (duration_us / 2) / 29.1; // Speed of sound ~343 m/s, so 29.1 cm/us

    printf("Distance: %.2f cm\n", distance_cm);

    cleanup(trigger_line, echo_line, chip);
    return EXIT_SUCCESS;
}

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>

#define GPIO_PIN 23
#define DEVICE_PATH "/dev/gpiochip0"
#define TIMEOUT_SECONDS 5

volatile sig_atomic_t keep_running = true;

void signal_handler(int signum) {
    keep_running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open(DEVICE_PATH);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line as output\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to get line value\n");
            break;
        }

        int new_value = 1 - value;
        ret = gpiod_line_set_value(line, new_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line value\n");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_PIN, new_value);
        sleep(TIMEOUT_SECONDS);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define MPU6050_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"
#define I2C_SLAVE_FORCE 0x0706

static int i2c_fd;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_msg messages[1];
    char buf[14];
    int16_t temp, gyro[3], accel[3];

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // MPU6050 power management register 0x6B
    buf[0] = 0x6B;
    buf[1] = 0x00; // Wake up the MPU6050
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to wake up MPU6050");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        messages[0].addr = MPU6050_ADDR;
        messages[0].flags = 0;
        messages[0].len = 14;
        messages[0].buf = buf;

        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            perror("Failed to read from MPU6050");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        temp = (buf[6] << 8) | buf[7];
        accel[0] = (buf[0] << 8) | buf[1];
        accel[1] = (buf[2] << 8) | buf[3];
        accel[2] = (buf[4] << 8) | buf[5];
        gyro[0] = (buf[8] << 8) | buf[9];
        gyro[1] = (buf[10] << 8) | buf[11];
        gyro[2] = (buf[12] << 8) | buf[13];

        printf("Temperature: %d°C\n", temp / 340.0 + 36.53);
        printf("Accel: X=%d, Y=%d, Z=%d\n", accel[0], accel[1], accel[2]);
        printf("Gyro: X=%d, Y=%d, Z=%d\n", gyro[0], gyro[1], gyro[2]);
        printf("--------------------\n");

        usleep(100000); // 0.1 second delay
    }

    return EXIT_SUCCESS;
}

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>

#define NUM_GPIOS 3
const int gpios[NUM_GPIOS] = {2, 3, 17};
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_GPIOS];
volatile sig_atomic_t keep_running = 1;

void cleanup(int signum) {
    keep_running = 0;
}

bool set_gpio_values(bool value) {
    int ret;
    for (int i = 0; i < NUM_GPIOS; i++) {
        ret = gpiod_line_set_value(lines[i], value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO %d\n", gpios[i]);
            return false;
        }
    }
    return true;
}

int main() {
    int ret;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_GPIOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", gpios[i]);
            goto cleanup_chip;
        }

        ret = gpiod_line_request_output(lines[i], "my_program", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line for GPIO %d\n", gpios[i]);
            goto cleanup_lines;
        }
    }

    for (int cycle = 0; cycle < 3 && keep_running; cycle++) {
        if (!set_gpio_values(1)) {
            goto cleanup_lines;
        }
        printf("Cycle %d: GPIO values set to HIGH\n", cycle + 1);
        sleep(5);

        if (!set_gpio_values(0)) {
            goto cleanup_lines;
        }
        printf("Cycle %d: GPIO values set to LOW\n", cycle + 1);
        sleep(5);
    }

cleanup_lines:
    for (int i = 0; i < NUM_GPIOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

cleanup_chip:
    if (chip) {
        gpiod_chip_close(chip);
    }

    return keep_running ? EXIT_SUCCESS : EXIT_FAILURE;
}

