#define I2C_BUS "/dev/i2c-1"
#define SHT31_ADDR 0x44
#define I2C_SLAVE_FORCE 0x0706

#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

#define SHT31_MEASURE_CMD 0x2C
#define SHT31_MEASURE_CMD_ARG 0x06

#define SHT31_CRC_POLYNOMIAL 0x131

static int i2c_fd = -1;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum == SIGINT ? 0 : 1);
}

uint8_t calculate_crc(uint8_t data[2]) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT31_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sht31(float *temperature, float *humidity) {
    uint8_t buffer[6];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (write(i2c_fd, &SHT31_MEASURE_CMD, 1) != 1) {
            perror("Failed to send measurement command");
            return -1;
        }
        usleep(50000); // 50ms delay for measurement

        if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
            perror("Failed to read from SHT31");
            return -1;
        }

        uint16_t raw_temp = (buffer[0] << 8) | buffer[1];
        uint16_t raw_humidity = (buffer[3] << 8) | buffer[4];
        uint8_t temp_crc = buffer[2];
        uint8_t humidity_crc = buffer[5];

        if (calculate_crc((uint8_t[]){buffer[0], buffer[1]}) != temp_crc ||
            calculate_crc((uint8_t[]){buffer[3], buffer[4]}) != humidity_crc) {
            fprintf(stderr, "CRC check failed\n");
            retries++;
            continue;
        }

        *temperature = -45.0 + 175.0 * (float)raw_temp / 65535.0;
        *humidity = 100.0 * (float)raw_humidity / 65535.0;

        return 0;
    }

    fprintf(stderr, "Failed to get valid reading after %d retries\n", RETRY_COUNT);
    return -1;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SHT31_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        float temperature, humidity;
        if (read_sht31(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read SHT31\n");
        }
        sleep(5);
    }

    return 0;
}

