    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    unsigned int n_buffers = 4;
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = n_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    for (unsigned int i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        void *mapped = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (mapped == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
            close(fd);
            return EXIT_FAILURE;
        }

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
            munmap(mapped, buf.length);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "Error starting capture: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *file = fopen(IMAGE_FILE, "wb");
    if (!file) {
        fprintf(stderr, "Error opening file for writing: %s\n", strerror(errno));
        munmap(mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset), buf.length);
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
        return EXIT_FAILURE;
    }

    if (fwrite(mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset), 1, buf.bytesused, file) != buf.bytesused) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        fclose(file);
        munmap(mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset), buf.length);
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
        return EXIT_FAILURE;
    }

    fclose(file);
    munmap(mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset), buf.length);

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "Error stopping capture: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    close(fd);
    return EXIT_SUCCESS;
}

