#include <errno.h>

#define GPIO_PIN 17
#define DEVICE_PATH "/dev/gpiochip0"
#define INTERVAL_USEC 50000

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open(DEVICE_PATH);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(-value));
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_PIN, value);

        ret = gpiod_line_set_value(line, 1 - value);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(-ret));
            break;
        }

        usleep(INTERVAL_USEC);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

