#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN1 18
#define GPIO_PIN2 27

static struct gpiod_chip *chip;
static struct gpiod_line *line1;
static struct gpiod_line *line2;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Request lines
    line1 = gpiod_chip_get_line(chip, GPIO_PIN1);
    line2 = gpiod_chip_get_line(chip, GPIO_PIN2);
    if (!line1 || !line2) {
        fprintf(stderr, "Error getting GPIO lines\n");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line1, "output1", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_PIN1, strerror(-ret));
        goto cleanup;
    }

    ret = gpiod_line_request_output(line2, "output2", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_PIN2, strerror(-ret));
        goto cleanup;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int state1 = 0, state2 = 0;
    while (keep_running) {
        ret = gpiod_line_set_value(line1, state1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d: %s\n", GPIO_PIN1, strerror(-ret));
            goto cleanup;
        }

        ret = gpiod_line_set_value(line2, state2);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d: %s\n", GPIO_PIN2, strerror(-ret));
            goto cleanup;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN1, state1, GPIO_PIN2, state2);

        state1 = !state1;
        state2 = !state2;

        usleep(10000); // 10ms = 0.01s
    }

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    return (ret < 0) ? EXIT_FAILURE : EXIT_SUCCESS;
}

