#define CYCLE_DELAY_US 500

void cleanup(int signum) {
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    for (int cycle = 0; cycle < NUM_CYCLES; cycle++) {
        // Set pixel color (example: red)
        if (gpioWrite(PIN, 1) < 0) {
            fprintf(stderr, "Failed to write to GPIO\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        usleep(CYCLE_DELAY_US);

        // Turn off pixel
        if (gpioWrite(PIN, 0) < 0) {
            fprintf(stderr, "Failed to write to GPIO\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        usleep(CYCLE_DELAY_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

