    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "my_program", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (!validity_check(value)) {
            fprintf(stderr, "Invalid value detected. Skipping this cycle.\n");
        } else {
            if (gpiod_line_set_value(line, value) < 0) {
                fprintf(stderr, "Failed to set GPIO line %d to value %d\n", GPIO_PIN, value);
            } else {
                printf("GPIO %d set to %d\n", GPIO_PIN, value);
            }
        }

        value = (value + 1) % 2;  // Toggle between 0 and 1
        sleep(VALIDITY_CHECK_INTERVAL);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define W1_BASE_PATH "/sys/bus/w1/devices/"
#define W1_SLAVE_FILE "w1_slave"
#define GPIO_PIN 4
#define NUM_READINGS 3
#define READING_INTERVAL 5

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int read_temperature(const char *device_path) {
    char path[256];
    char buffer[256];
    int fd, ret;

    snprintf(path, sizeof(path), "%s/%s", device_path, W1_SLAVE_FILE);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open w1_slave file");
        return -1;
    }

    ret = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);
    if (ret < 0) {
        perror("Failed to read w1_slave file");
        return -1;
    }
    buffer[ret] = '\0';

    char *temp_pos = strstr(buffer, "t=");
    if (!temp_pos) {
        fprintf(stderr, "Temperature data not found\n");
        return -1;
    }

    return atoi(temp_pos + 2) / 1000;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    DIR *dir;
    struct dirent *entry;
    char device_path[256];
    int found = 0;

    dir = opendir(W1_BASE_PATH);
    if (!dir) {
        perror("Failed to open w1 bus directory");
        return EXIT_FAILURE;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strncmp(entry->d_name, "28-", 3) == 0) {
            snprintf(device_path, sizeof(device_path), "%s%s", W1_BASE_PATH, entry->d_name);
            found = 1;
            break;
        }
    }
    closedir(dir);

    if (!found) {
        fprintf(stderr, "DS18B20 device not found\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_READINGS && keep_running; i++) {
        int temperature = read_temperature(device_path);
        if (temperature < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            return EXIT_FAILURE;
        }
        printf("Temperature: %d°C\n", temperature);
        sleep(READING_INTERVAL);
    }

    return EXIT_SUCCESS;
}

