#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define TRIG_PIN 18
#define ECHO_PIN 23
#define GPIO_CHIP "gpiochip0"

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile sig_atomic_t keep_running = 1;

void cleanup(int signum) {
    keep_running = 0;
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int initialize_gpio() {
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!trigger_line || !echo_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "HC-SR04-Trigger", 0) < 0 ||
        gpiod_line_request_input(echo_line, "HC-SR04-Echo") < 0) {
        perror("Failed to request GPIO lines");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void release_gpio() {
    if (trigger_line) gpiod_line_release(trigger_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
}

int measure_distance() {
    const int timeout_us = 30000; // 30ms timeout
    struct timespec start, current;
    int64_t elapsed_us;

    gpiod_line_set_value(trigger_line, 1);
    usleep(10); // 10 microseconds
    gpiod_line_set_value(trigger_line, 0);

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &current);
        elapsed_us = (current.tv_sec - start.tv_sec) * 1000000 + (current.tv_nsec - start.tv_nsec) / 1000;
        if (elapsed_us > timeout_us) return -1; // Timeout
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &current);
        elapsed_us = (current.tv_sec - start.tv_sec) * 1000000 + (current.tv_nsec - start.tv_nsec) / 1000;
        if (elapsed_us > timeout_us) return -1; // Timeout
    }

    // Speed of sound is 343 m/s, and we need to divide by 2 because the signal travels to the object and back
    return (int)((elapsed_us * 34300) / 20000); // Distance in cm
}

int main() {
    if (initialize_gpio() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    setup_signal_handlers();

    while (keep_running) {
        int distance = measure_distance();
        if (distance >= 0) {
            printf("Distance: %d cm\n", distance);
        } else {
            printf("Error or timeout measuring distance\n");
        }
        usleep(100000); // 0.1 seconds
    }

    release_gpio();
    return EXIT_SUCCESS;
}

