#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define PWM_PIN1 4
#define PWM_PIN2 17
#define PWM_PIN3 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define PWM_DUTY_CYCLE 500
#define INTERVAL_MS 100

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN1, PI_OUTPUT) < 0 ||
        gpioSetMode(PWM_PIN2, PI_OUTPUT) < 0 ||
        gpioSetMode(PWM_PIN3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN1, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(PWM_PIN2, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(PWM_PIN3, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (keep_running) {
        if (gpioPWM(PWM_PIN1, PWM_DUTY_CYCLE) < 0 ||
            gpioPWM(PWM_PIN2, PWM_DUTY_CYCLE) < 0 ||
            gpioPWM(PWM_PIN3, PWM_DUTY_CYCLE) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }

        printf("PWM set on GPIO %d, %d, %d\n", PWM_PIN1, PWM_PIN2, PWM_PIN3);
        fflush(stdout);

        usleep(INTERVAL_MS * 1000);
    }

    gpioSetPWM(PWM_PIN1, 0) < 0;
    gpioSetPWM(PWM_PIN2, 0) < 0;
    gpioSetPWM(PWM_PIN3, 0) < 0;

    gpioTerminate();
    return EXIT_SUCCESS;
}

