#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define DHT_PIN 4
#define NUM_CYCLES 3
#define TIMEOUT_US 1000000

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int read_dht22(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Failed to get line\n");
        return -1;
    }

    int ret = gpiod_line_request_input(line, "DHT22");
    if (ret < 0) {
        fprintf(stderr, "Failed to request line as input\n");
        gpiod_line_release(line);
        return -1;
    }

    int data[5] = {0};
    int bit_count = 0;
    int byte_count = 0;
    int last_state = 1;
    int bits = 0;
    int cycles = 0;

    while (keep_running && cycles < NUM_CYCLES) {
        int state = gpiod_line_get_value(line);
        if (state == -1) {
            fprintf(stderr, "Failed to read line value\n");
            gpiod_line_release(line);
            return -1;
        }

        if (state != last_state) {
            bits++;
            if (bits >= 2) {
                data[byte_count] = (data[byte_count] << 1) | (state == 0);
                bits = 0;
                if (++bit_count >= 8) {
                    bit_count = 0;
                    if (++byte_count >= 5) {
                        byte_count = 0;
                        cycles++;
                        printf("Cycle %d: Humidity: %d.%d%%, Temperature: %d.%d°C\n",
                               cycles, data[0], data[1], data[2], data[3]);
                    }
                }
            }
        }
        last_state = state;
        usleep(10);
    }

    gpiod_line_release(line);
    return cycles == NUM_CYCLES ? 0 : -1;
}

int main() {
    struct gpiod_chip *chip;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    ret = read_dht22(chip, DHT_PIN);
    if (ret != 0) {
        fprintf(stderr, "Failed to read DHT22 data\n");
    }

    gpiod_chip_close(chip);
    return ret == 0 ? EXIT_SUCCESS : EXIT_FAILURE;
}

