int read_dht22() {
    struct timespec start, current;
    int data[5] = {0};
    int bit_count = 0;
    int byte_count = 0;
    int last_state = 1;
    int current_state;
    int high_time = 0;
    int low_time = 0;

    gpiod_line_request_input(line, "DHT22");

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        current_state = gpiod_line_get_value(line);
        clock_gettime(CLOCK_MONOTONIC, &current);

        if (current_state != last_state) {
            high_time = (current.tv_sec - start.tv_sec) * 1000000 + (current.tv_nsec - start.tv_nsec) / 1000;
            start = current;
            last_state = current_state;

            if (current_state == 0) {
                if (high_time > 80000 && high_time < 100000) {
                    bit_count = 0;
                    byte_count = 0;
                } else if (high_time > 200 && high_time < 400) {
                    data[byte_count] = (data[byte_count] << 1) | 0;
                } else if (high_time > 600 && high_time < 800) {
                    data[byte_count] = (data[byte_count] << 1) | 1;
                }
            }

            if (bit_count >= 40) {
                int checksum = data[0] + data[1] + data[2] + data[3];
                if (checksum == data[4]) {
                    printf("Temperature: %.1f°C, Humidity: %.1f%%\n", 
                           (float)data[2] + (float)data[3] / 10.0, 
                           (float)data[0] + (float)data[1] / 10.0);
                    return 0;
                }
                return -1;
            }

            if (bit_count == 8) {
                bit_count = 0;
                byte_count++;
            } else {
                bit_count++;
            }
        }

        if ((current.tv_sec - start.tv_sec) * 1000000 + (current.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_US) {
            return -1;
        }
    }
}

