#define MAX31855_CR1 0x01
#define MAX31855_LTCBH 0x06
#define MAX31855_LTCBL 0x07
#define MAX31855_LTCBH_ERR 0x08
#define MAX31855_LTCBL_ERR 0x09

int spifd;

void cleanup(int status) {
    if (spifd >= 0) {
        close(spifd);
    }
    exit(status);
