int main() {
    struct timespec start, end;
    long elapsed_ns;

    // Set up signal handler
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    trigger_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trigger_line || !echo_line) {
        perror("Failed to get GPIO lines");
        cleanup(0);
    }

    // Configure lines
    gpiod_line_request_output(trigger_line, "hc_sr04_trigger", 0);
    gpiod_line_request_input(echo_line, "hc_sr04_echo");

    // Trigger pulse
    gpiod_line_set_value(trigger_line, 1);
    usleep(10); // 10 microseconds
    gpiod_line_set_value(trigger_line, 0);

    // Wait for echo
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000) {
            printf("Timeout waiting for echo\n");
            cleanup(0);
        }
    }

    // Measure echo pulse
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000) {
            printf("Timeout measuring echo pulse\n");
            cleanup(0);
        }
    }

    // Calculate distance
    double distance_cm = (elapsed_ns / 1000000000.0) * 34300 / 2;
    printf("Distance: %.2f cm\n", distance_cm);

    cleanup(0);
    return EXIT_SUCCESS;
}

