#include <time.h>
#include <signal.h>
#include <stdbool.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define MAX_DISTANCE_CM 400
#define SPEED_OF_SOUND 34300 // in cm/s
#define TIMEOUT_US 30000 // 30 ms timeout

static volatile bool keep_running = true;

void signal_handler(int signum) {
    keep_running = false;
}

bool check_distance_validity(int distance_cm) {
    return distance_cm >= 0 && distance_cm <= MAX_DISTANCE_CM;
}

int measure_distance(struct gpiod_chip *chip, int trigger_fd, int echo_fd) {
    gpiod_line_set_value(trigger_fd, 1);
    usleep(10); // 10 microseconds
    gpiod_line_set_value(trigger_fd, 0);

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    int timeout = 0;
    while (gpiod_line_get_value(echo_fd) == 0) {
        if (timeout++ > TIMEOUT_US) {
            return -1; // Timeout
        }
        usleep(1);
    }

    timeout = 0;
    clock_gettime(CLOCK_MONOTONIC, &end);
    while (gpiod_line_get_value(echo_fd) == 1) {
        if (timeout++ > TIMEOUT_US) {
            return -1; // Timeout
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
    }

    double time_elapsed = (end.tv_sec - start.tv_sec) * 1e9 + (end.tv_nsec - start.tv_nsec);
    int distance_cm = (int)((time_elapsed / 2) / 29.1); // Speed of sound in cm/us / 2

    return check_distance_validity(distance_cm) ? distance_cm : -1;
}

