#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53

static int i2c_fd;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_msg messages[1];
    char buf[6];
    int16_t x, y, z;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set to measure mode
    buf[0] = 0x2D;
    buf[1] = 0x08;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to ADXL345");
        cleanup(0);
    }

    messages[0].addr = ADXL345_ADDR;
    messages[0].flags = I2C_M_RD;
    messages[0].len = 6;
    messages[0].buf = buf;

    if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
        perror("Failed to read from ADXL345");
        cleanup(0);
    }

    x = (buf[1] << 8) | buf[0];
    y = (buf[3] << 8) | buf[2];
    z = (buf[5] << 8) | buf[4];

    printf("X: %d, Y: %d, Z: %d\n", x, y, z);

    cleanup(0);
    return EXIT_SUCCESS;
}

