#define TRIG_PIN 4
#define ECHO_PIN 17
#define GPIO_CHIP "gpiochip0"
#define TIMEOUT_US 1000000  // 1 second timeout

static struct gpiod_chip *chip;
static struct gpiod_line *trig_line;
static struct gpiod_line *echo_line;
static volatile sig_atomic_t keep_running = 1;

void cleanup(int signum) {
    keep_running = 0;
}

int setup_gpio() {
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!trig_line || !echo_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(trig_line, "HC-SR04-TRIG", 0) < 0 ||
        gpiod_line_request_input(echo_line, "HC-SR04-ECHO") < 0) {
        perror("Failed to request GPIO lines");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void release_gpio() {
    if (trig_line) gpiod_line_release(trig_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
}

int measure_distance() {
    struct timespec start, end;
    int64_t elapsed_ns;

    // Send 10us pulse
    gpiod_line_set_value(trig_line, 1);
    nanosleep(&(struct timespec){0, 10000}, NULL);
    gpiod_line_set_value(trig_line, 0);

    // Wait for echo
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
            perror("clock_gettime");
            return -1;
        }
        elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000) {
            fprintf(stderr, "Echo pulse timeout\n");
            return -1;
        }
    }

    // Measure pulse duration
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
            perror("clock_gettime");
            return -1;
        }
        elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000) {
            fprintf(stderr, "Echo pulse timeout\n");
            return -1;
        }
    }

    // Calculate distance (speed of sound ~343 m/s, round trip)
    return (int)((elapsed_ns / 1000000000.0) * 17150);
}

int main() {
    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (keep_running) {
        int distance = measure_distance();
        if (distance >= 0) {
            printf("Distance: %d cm\n", distance);
        } else {
            printf("Measurement failed\n");
        }
        usleep(100000);  // 0.1 seconds
    }

    release_gpio();
    return EXIT_SUCCESS;
}

