#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDRESS 0x29
#define I2C_SLAVE_FORCE 0x0706

#define COMMAND_BIT 0x80
#define ENABLE_REG 0x00
#define ATIME_REG 0x01
#define CONTROL_REG 0x0F
#define CDATA_REG 0x14

#define ENABLE_POWER 0x01
#define ENABLE_AEN 0x02

#define INTEGRATION_TIME_2_4MS 0xFF
#define GAIN_1X 0x00

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int write_i2c(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg | COMMAND_BIT;
    buf[1] = value;
    return write(fd, buf, 2);
}

int read_i2c(int fd, uint8_t reg, uint8_t *buf, int len) {
    uint8_t cmd = reg | COMMAND_BIT;
    if (write(fd, &cmd, 1) != 1) return -1;
    return read(fd, buf, len);
}

int main() {
    int fd;
    uint8_t buf[6];
    uint16_t clear, red, green, blue;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE_FORCE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    if (write_i2c(fd, ENABLE_REG, ENABLE_POWER) < 0 ||
        write_i2c(fd, ATIME_REG, INTEGRATION_TIME_2_4MS) < 0 ||
        write_i2c(fd, CONTROL_REG, GAIN_1X) < 0 ||
        write_i2c(fd, ENABLE_REG, ENABLE_POWER | ENABLE_AEN) < 0) {
        perror("Failed to configure TCS34725");
        close(fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (read_i2c(fd, CDATA_REG, buf, 6) != 6) {
            fprintf(stderr, "Failed to read from TCS34725\n");
            break;
        }

        clear = (buf[1] << 8) | buf[0];
        red = (buf[3] << 8) | buf[2];
        green = (buf[5] << 8) | buf[4];
        blue = (buf[7] << 8) | buf[6];

        printf("Clear: %d, Red: %d, Green: %d, Blue: %d\n", clear, red, green, blue);

        usleep(500000);  // Sleep for 0.5 seconds
    }

    write_i2c(fd, ENABLE_REG, 0x00);  // Disable the sensor
    close(fd);
    return EXIT_SUCCESS;
}

