#include <unistd.h>
#include <time.h>
#include <signal.h>

#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define GPIO_CHIP "gpiochip0"
#define TIMEOUT_US 1000000  // 1 second timeout

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;

void cleanup(int signum) {
    if (trigger_line) gpiod_line_release(trigger_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec start, end;
    long elapsed_ns;

    // Set up signal handler
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trigger_line || !echo_line) {
        perror("Failed to get GPIO lines");
        cleanup(0);
    }

    // Configure lines
    if (gpiod_line_request_output(trigger_line, "HC-SR04 Trigger", 0) < 0 ||
        gpiod_line_request_input(echo_line, "HC-SR04 Echo") < 0) {
        perror("Failed to configure GPIO lines");
        cleanup(0);
    }

    // Trigger pulse
    gpiod_line_set_value(trigger_line, 1);
    usleep(10);  // 10 microseconds
    gpiod_line_set_value(trigger_line, 0);

    // Wait for echo
    clock_gettime(CLOCK_MONOTONIC, &start);
    int echo_state = 0;
    do {
        echo_state = gpiod_line_get_value(echo_line);
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
    } while (echo_state == 0 && elapsed_ns < TIMEOUT_US);

    if (echo_state == 0) {
        printf("Echo not received within timeout\n");
        cleanup(0);
    }

    // Measure echo pulse duration
    clock_gettime(CLOCK_MONOTONIC, &start);
    do {
        echo_state = gpiod_line_get_value(echo_line);
        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
    } while (echo_state == 1 && elapsed_ns < TIMEOUT_US);

    if (echo_state == 1) {
        printf("Echo pulse too long\n");
        cleanup(0);
    }

    // Calculate distance (speed of sound ~343 m/s)
    double distance_cm = (elapsed_ns / 1000000000.0) * 17150.0;
    printf("Distance: %.2f cm\n", distance_cm);

    cleanup(0);
    return EXIT_SUCCESS;
}

