volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        gpioPWM(PWM_PIN, PWM_DUTY_CYCLE);
        printf("PWM state: ON\n");

        gpioSleep(Time_release, 0, INTERVAL_MS / 2);

        gpioPWM(PWM_PIN, 0);
        printf("PWM state: OFF\n");

        gpioSleep(Time_release, 0, INTERVAL_MS / 2);
    }

    gpioSetPWMfrequency(PWM_PIN, 0);  // Stop PWM
    gpioTerminate();

    return EXIT_SUCCESS;
}

