#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define MPU6050_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"
#define I2C_SLAVE_FORCE 0x0706

static int i2c_fd;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        printf("\nInterrupt received, cleaning up...\n");
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_msg messages[1];
    char buffer[14];
    int16_t temp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // MPU6050 power management register 0x6B
    buffer[0] = 0x6B;
    buffer[1] = 0x00; // Wake up the MPU6050
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to I2C slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        // MPU6050 data register 0x3B
        buffer[0] = 0x3B;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to I2C slave");
            break;
        }

        messages[0].addr = MPU6050_ADDR;
        messages[0].flags = I2C_M_RD;
        messages[0].len = 14;
        messages[0].buf = buffer;

        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            perror("Failed to read from I2C slave");
            break;
        }

        temp = (buffer[0] << 8) | buffer[1];
        gyro_x = (buffer[8] << 8) | buffer[9];
        gyro_y = (buffer[10] << 8) | buffer[11];
        gyro_z = (buffer[12] << 8) | buffer[13];
        accel_x = (buffer[2] << 8) | buffer[3];
        accel_y = (buffer[4] << 8) | buffer[5];
        accel_z = (buffer[6] << 8) | buffer[7];

        printf("Temp: %d°C, Gyro: X=%d, Y=%d, Z=%d, Accel: X=%d, Y=%d, Z=%d\n",
               temp / 340.00 + 36.53, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        sleep(1);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>

#define GPIO_PIN 17
#define INTERVAL_SECONDS 0.6

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile bool running = true;

void signal_handler(int signum) {
    running = false;
}

int main() {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "my_program", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Set GPIO to HIGH
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO HIGH\n");
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        sleep(INTERVAL_SECONDS);

        // Set GPIO to LOW
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO LOW\n");
            break;
